CREATE TABLE public.extract_test(name text PRIMARY KEY,result jsonb,started jsonb);
GRANT ALL ON public.extract_test TO authenticated,service_role;
CREATE FUNCTION public.test_extract(i uuid,t uuid DEFAULT NULL,r integer DEFAULT NULL,body text DEFAULT 'Neutral extracted text') RETURNS jsonb LANGUAGE sql SECURITY INVOKER AS $$
 SELECT public.submit_knowledge_extraction('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001',i,t,r,'Test source',body,NULL)$$;
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000001',false);
SET ROLE authenticated;
SELECT public.test_denied($q$SELECT public.test_extract(gen_random_uuid())$q$,'permission denied');
SELECT public.test_denied($q$SELECT public.start_knowledge_extraction(NULL)$q$,'permission denied');
SELECT public.test_denied($q$SELECT public.complete_knowledge_extraction(NULL,NULL,NULL,NULL,NULL,NULL)$q$,'permission denied');
SELECT public.test_denied($q$SELECT public.resolve_knowledge_extraction_source(NULL,NULL,NULL)$q$,'permission denied');
SELECT public.test_denied($q$UPDATE public.tenant_knowledge_docs SET pending_review=NULL WHERE title='A'$q$,'permission denied');
SELECT public.test_denied($q$INSERT INTO public.tenant_knowledge_docs(id,tenant_id,title,content,record_state) VALUES(gen_random_uuid(),'00000000-0000-0000-0000-000000000001','bad','','draft')$q$,'permission denied');
INSERT INTO public.tenant_knowledge_docs(id,tenant_id,title,content,created_by) VALUES('20000000-0000-0000-0000-000000000009','00000000-0000-0000-0000-000000000001','Legacy insert','Legacy content','10000000-0000-0000-0000-000000000001');
UPDATE public.tenant_knowledge_docs SET summary='Legacy update' WHERE title='Legacy insert';
SELECT public.test_assert((SELECT summary='Legacy update' AND revision=2 FROM public.tenant_knowledge_docs WHERE title='Legacy insert'),'legacy authenticated writes preserved');
RESET ROLE;
SET ROLE anon;
SELECT public.test_denied($q$SELECT public.recover_knowledge_extraction(10)$q$,'permission denied');
RESET ROLE;
SET ROLE service_role;
INSERT INTO public.extract_test VALUES('new',public.test_extract('70000000-0000-0000-0000-000000000001'),NULL);
SELECT public.test_assert(public.test_extract('70000000-0000-0000-0000-000000000001')->>'replayed'='true','identical intent replay');
SELECT public.test_denied($q$SELECT public.test_extract('70000000-0000-0000-0000-000000000001',NULL,NULL,'Different text')$q$,'DURABLE_WORK_INTENT_REPLAY_MISMATCH');
UPDATE public.extract_test SET started=public.start_knowledge_extraction((result->>'work_id')::uuid) WHERE name='new';
SELECT public.test_denied(format('SELECT public.start_knowledge_extraction(%L)',(SELECT result->>'work_id' FROM public.extract_test WHERE name='new')),'KNOWLEDGE_WORK_NOT_CLAIMABLE');
SELECT public.test_denied(format('SELECT public.complete_knowledge_extraction(%L,%L,2,1,%L,%L)',(SELECT result->>'work_id' FROM public.extract_test WHERE name='new'),(SELECT started->>'server_key' FROM public.extract_test WHERE name='new'),'Neutral extracted text',encode(sha256(convert_to('Neutral extracted text','UTF8')),'hex')),'KNOWLEDGE_ATTEMPT_STALE');
SELECT public.test_assert((SELECT public.complete_knowledge_extraction((result->>'work_id')::uuid,started->>'server_key',1,1,'Neutral extracted text',started->>'input_hash')->>'phase'='awaiting_review' FROM public.extract_test WHERE name='new'),'paste completes only into review');
RESET ROLE;
SELECT public.test_assert((SELECT record_state='draft' AND content='' AND source_binding IS NULL AND pending_review->>'extracted_content'='Neutral extracted text' AND extraction_input IS NULL FROM public.tenant_knowledge_docs WHERE id=(SELECT (result->>'document_id')::uuid FROM public.extract_test WHERE name='new')),'draft remains unpublished and intake cleared');
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM public.paige_durable_work WHERE request_payload::text LIKE '%Neutral extracted text%'),'raw text absent from job payload');
SET ROLE authenticated;
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM public.tenant_knowledge_docs WHERE title='Test source'),'draft hidden from direct legacy read');
SELECT public.test_denied('SELECT extraction_input FROM public.tenant_knowledge_docs','permission denied');
SELECT public.test_assert(public.read_tenant_knowledge_review('00000000-0000-0000-0000-000000000001',(SELECT (result->>'document_id')::uuid FROM public.extract_test WHERE name='new'))->'pending_review'->>'extracted_content'='Neutral extracted text','scoped review exposes extracted text');
RESET ROLE;
SET ROLE service_role;
INSERT INTO public.extract_test VALUES('replacement',public.test_extract('70000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001',1),NULL);
SELECT public.test_denied($q$SELECT public.test_extract('70000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001',2)$q$,'KNOWLEDGE_REVIEW_PENDING');
UPDATE public.extract_test SET started=public.start_knowledge_extraction((result->>'work_id')::uuid) WHERE name='replacement';
SELECT set_config('test.receipt_fail','true',false);
SELECT public.test_assert((SELECT public.complete_knowledge_extraction((result->>'work_id')::uuid,started->>'server_key',1,2,'Neutral extracted text',started->>'input_hash')->>'outcome'='capability_completed_unrecorded' FROM public.extract_test WHERE name='replacement'),'receipt failure preserves verified extraction');
SELECT set_config('test.receipt_fail','false',false);
RESET ROLE;
SELECT public.test_assert((SELECT content='private A' AND source_binding IS NULL AND record_state='canonical' AND pending_review IS NOT NULL FROM public.tenant_knowledge_docs WHERE title='A'),'replacement preserves old canonical content');
SELECT public.test_assert((SELECT content='A chunk' FROM public.tenant_knowledge_chunks WHERE doc_id='20000000-0000-0000-0000-000000000001'),'replacement preserves old chunks');
SET ROLE service_role;
INSERT INTO public.extract_test VALUES('changed',public.test_extract('70000000-0000-0000-0000-000000000004'),NULL);
UPDATE public.extract_test SET started=public.start_knowledge_extraction((result->>'work_id')::uuid) WHERE name='changed';
RESET ROLE;
UPDATE public.tenant_knowledge_docs SET summary='concurrent metadata' WHERE id=(SELECT (result->>'document_id')::uuid FROM public.extract_test WHERE name='changed');
SET ROLE service_role;
SELECT public.test_denied(format('SELECT public.complete_knowledge_extraction(%L,%L,1,1,%L,%L)',(SELECT result->>'work_id' FROM public.extract_test WHERE name='changed'),(SELECT started->>'server_key' FROM public.extract_test WHERE name='changed'),'Neutral extracted text',encode(sha256(convert_to('Neutral extracted text','UTF8')),'hex')),'KNOWLEDGE_REVISION_CONFLICT');
INSERT INTO public.extract_test VALUES('revoked',public.test_extract('70000000-0000-0000-0000-000000000005'),NULL);
UPDATE public.extract_test SET started=public.start_knowledge_extraction((result->>'work_id')::uuid) WHERE name='revoked';
RESET ROLE;
UPDATE public.tenant_members SET status='inactive' WHERE user_id='10000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT public.test_denied(format('SELECT public.complete_knowledge_extraction(%L,%L,1,1,%L,%L)',(SELECT result->>'work_id' FROM public.extract_test WHERE name='revoked'),(SELECT started->>'server_key' FROM public.extract_test WHERE name='revoked'),'Neutral extracted text',encode(sha256(convert_to('Neutral extracted text','UTF8')),'hex')),'KNOWLEDGE_SCOPE_CHANGED');
RESET ROLE;
UPDATE public.tenant_members SET status='active' WHERE user_id='10000000-0000-0000-0000-000000000001';
SET ROLE service_role;
INSERT INTO public.extract_test VALUES('missed',public.test_extract('70000000-0000-0000-0000-000000000006'),NULL);
RESET ROLE;
UPDATE public.paige_durable_work SET lease_until=now()-interval '1 second' WHERE id IN (SELECT (result->>'work_id')::uuid FROM public.extract_test WHERE name IN ('missed','changed'));
SET ROLE service_role;
SELECT public.test_assert((SELECT count(*)=1 FROM public.recover_knowledge_extraction(10)),'only missed predispatch wake is retried');
RESET ROLE;
SELECT public.test_assert((SELECT status='outcome_unknown' FROM public.paige_durable_work WHERE id=(SELECT (result->>'work_id')::uuid FROM public.extract_test WHERE name='changed')),'dispatched expiry needs reconciliation');
SELECT public.test_assert((SELECT attempt_count=2 AND status='claimed' FROM public.paige_durable_work WHERE id=(SELECT (result->>'work_id')::uuid FROM public.extract_test WHERE name='missed')),'missed wake advances native attempt');
INSERT INTO storage.objects VALUES('40000000-0000-0000-0000-000000000002','tenant-knowledge','00000000-0000-0000-0000-000000000001/source.txt');
SET ROLE service_role;
INSERT INTO public.extract_test SELECT 'file',public.submit_knowledge_extraction('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000007',NULL,NULL,'File source',NULL,jsonb_build_object('bucket','tenant-knowledge','object_id','40000000-0000-0000-0000-000000000002','object_name','00000000-0000-0000-0000-000000000001/source.txt','sha256',encode(sha256(convert_to('File bytes','UTF8')),'hex'),'byte_size',10,'mime_type','text/plain','bound_at','2026-10-01T00:00:00Z')),NULL;
UPDATE public.extract_test SET started=public.start_knowledge_extraction((result->>'work_id')::uuid) WHERE name='file';
SELECT public.test_denied(format('SELECT public.complete_knowledge_extraction(%L,%L,1,1,%L,%L)',(SELECT result->>'work_id' FROM public.extract_test WHERE name='file'),(SELECT started->>'server_key' FROM public.extract_test WHERE name='file'),'Changed bytes',encode(sha256(convert_to('Changed bytes','UTF8')),'hex')),'KNOWLEDGE_OUTPUT_INVALID');
RESET ROLE;
DELETE FROM storage.objects WHERE id='40000000-0000-0000-0000-000000000002';
SET ROLE service_role;
SELECT public.test_denied(format('SELECT public.complete_knowledge_extraction(%L,%L,1,1,%L,%L)',(SELECT result->>'work_id' FROM public.extract_test WHERE name='file'),(SELECT started->>'server_key' FROM public.extract_test WHERE name='file'),'File bytes',encode(sha256(convert_to('File bytes','UTF8')),'hex')),'KNOWLEDGE_SOURCE_CHANGED');
RESET ROLE;
SET ROLE authenticated;
SELECT public.test_assert(public.delete_tenant_knowledge('00000000-0000-0000-0000-000000000001',(SELECT (result->>'document_id')::uuid FROM public.extract_test WHERE name='new'),2)->>'document_absent'='true','pending extraction draft can be deleted without source cleanup');
RESET ROLE;

-- Existing native document adoption remains separate and functional after activation.
SET ROLE authenticated;
INSERT INTO public.extract_test SELECT 'document',jsonb_build_object('work_id',work_id),NULL FROM public.submit_paige_document_work('70000000-0000-0000-0000-000000000011','50000000-0000-0000-0000-000000000001','{"version":1,"doc_type":"guide","title":"Guide","brief":"Neutral test guide"}');
SELECT public.test_assert((SELECT resumed_existing FROM public.submit_paige_document_work('70000000-0000-0000-0000-000000000011','50000000-0000-0000-0000-000000000001','{"version":1,"doc_type":"guide","title":"Guide","brief":"Neutral test guide"}')),'old native document replay preserved');
SELECT public.test_assert((SELECT count(*)=1 FROM public.get_paige_durable_work((SELECT (result->>'work_id')::uuid FROM public.extract_test WHERE name='document'))),'old native document status preserved');
RESET ROLE;
SET ROLE service_role;
SELECT public.test_assert((SELECT work_status='claimed' FROM public.start_paige_document_work_execution((SELECT (result->>'work_id')::uuid FROM public.extract_test WHERE name='document'))),'old document dispatch preserved');
INSERT INTO public.extract_test SELECT 'operator',public.submit_knowledge_extraction('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000003','70000000-0000-0000-0000-000000000012',NULL,NULL,'Operator input','Operator text',NULL),NULL;
UPDATE public.extract_test SET started=public.start_knowledge_extraction((result->>'work_id')::uuid) WHERE name='operator';
SELECT public.test_assert((SELECT public.complete_knowledge_extraction((result->>'work_id')::uuid,started->>'server_key',1,1,'Operator text',started->>'input_hash')->>'outcome'='capability_completed_unrecorded' FROM public.extract_test WHERE name='operator'),'company operator extraction preserves receipt authority distinction');
RESET ROLE;
INSERT INTO storage.objects VALUES('40000000-0000-0000-0000-000000000002','tenant-knowledge','00000000-0000-0000-0000-000000000001/source.txt');
SET ROLE service_role;
SELECT public.test_assert((SELECT public.complete_knowledge_extraction((result->>'work_id')::uuid,started->>'server_key',1,1,'File bytes',started->>'input_hash')->>'phase'='awaiting_review' FROM public.extract_test WHERE name='file'),'file frozen hash produces pending review only');
RESET ROLE;
SELECT public.test_assert((SELECT source_binding IS NULL AND extraction_source_binding->>'sha256'=encode(sha256(convert_to('File bytes','UTF8')),'hex') FROM public.tenant_knowledge_docs WHERE id=(SELECT (result->>'document_id')::uuid FROM public.extract_test WHERE name='file')),'candidate source binding does not claim published source');
